    /**
     * Tests getting all Claims.
     *
     * @return    Collection
     */
    public List<Claim> testGetAll() throws Throwable {
    LOGGER.info( "ClaimTest:testGetAll() - Retrieving Collection of Claims:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Claim : " );
    List<Claim> collection  = null;

    try {
        // call the static get method on the ClaimService
        collection = service.getAllClaim();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Claim currEntity  = null;
            Iterator<Claim> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getClaimId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

